// t02: balancing and closing ledger accounts (balance c/d and b/d for real and personal accounts; nominal accounts
// closed by transfer to Trading or Profit and Loss); reading debit and credit balances. Imagined firms; ledgers
// are generated by acc.mjs ledger()/post() and asserted.
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, sum, inr, rs, mdTable, ledger, post, postD, showL, lmd, acct, postedOnly, openingsFrom, E1 } from './fig.mjs';
import { QQ, numQ } from './qq.mjs';

// ================================================================ multiple choice
const HH = ledger({ name: 'Cash A/c', dr: [['To Balance b/d', 120000], ['To Sales A/c', 64000]], cr: [['By Purchases A/c', 90000], ['By Rent A/c', 62000]] });
same(HH.balance, 32000, 'Hoshiarpur balance');
same(HH.total, 184000, 'Hoshiarpur total');
QQ('m_balance_side', mcq({
  t: 2, d: 2, c: 'application',
  stem: 'In the Cash A/c of Hoshiarpur Hosiery, an imagined firm, the debit side adds up to ₹1,84,000 and the credit side to ₹1,52,000. The account is balanced as',
  opts: ['a debit balance of ₹32,000, written as By Balance c/d on the credit side', 'a credit balance of ₹32,000, written as To Balance c/d on the debit side', 'a debit balance of ₹32,000, written as To Balance c/d on the debit side', 'a balance of ₹3,36,000, the sum of the two sides'],
  sol: 'The debit side is larger by ₹32,000, so the balance is a debit balance. It is entered on the smaller, credit, side as By Balance c/d to make the two totals equal. Putting it on the debit side would raise the larger side again, and the sum of the two sides is not a balance at all.',
}));
QQ('m_cd_bd', mcq({
  t: 2, d: 1, c: 'recall',
  stem: 'Kalyani Bakery, an imagined firm, balances its Cash A/c on 31 March 2028 and writes By Balance c/d on the credit side. On 1 April 2028 the balance is brought down as',
  opts: ['To Balance b/d on the debit side', 'By Balance b/d on the credit side', 'To Balance b/d on the credit side', 'By Balance b/d on the debit side'],
  sol: 'A balance carried down on the credit side is a debit balance, so it is brought down on the debit side as To Balance b/d, below the totals. The other three put the word or the side wrongly.',
}));
QQ('m_nominal_close', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'At the end of the year the Salaries A/c of Jamui Tutors, an imagined firm, shows a debit total of ₹54,000. The account is',
  opts: ['closed by transferring ₹54,000 to the Profit and Loss Account, with no balance c/d', 'balanced by writing By Balance c/d ₹54,000 and carrying it to the next year', 'transferred to the Balance Sheet as an asset of ₹54,000', 'transferred to the Capital Account as drawings'],
  sol: 'Salaries is an indirect expense, a nominal account, so it is closed by transfer to the Profit and Loss Account and starts the new year empty. Only real and personal accounts are carried down, and an expense is neither an asset nor drawings.',
}));
const BT = ledger({ name: 'Sundar Plastics A/c', opening: { side: 'cr', amount: 24000 }, dr: [['To Cash A/c', 40000], ['To Purchases Return A/c', 4000]], cr: [['By Purchases A/c', 36000]] });
same(BT.balance, -16000, 'Sundar Plastics balance');
QQ('m_creditor_balance', mcq({
  t: 2, d: 3, c: 'application',
  stem: 'The account of Sundar Plastics, a supplier of Bellary Traders (an imagined firm), shows an opening credit balance of ₹24,000, goods bought on credit ₹36,000, cash paid ₹40,000 and goods returned ₹4,000. The closing balance is',
  opts: [rs(16000) + ' credit', rs(16000) + ' debit', rs(32000) + ' credit', rs(44000) + ' credit'],
  sol: `Credit side ${inr(24000)} + ${inr(36000)} = ${inr(60000)}; debit side ${inr(40000)} + ${inr(4000)} = ${inr(44000)}; the credit side is larger by ${inr(16000)}, which is still owed. A debit balance reverses the sides, ${rs(32000)} forgets the return, and ${rs(44000)} is just the debit total.`,
}));
QQ('m_nature_balance', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'After balancing its ledger, Vizag Chilli Traders, an imagined firm, lists the balances of its accounts. The account that normally shows a credit balance is',
  opts: ['Capital A/c', 'Cash A/c', 'Machinery A/c', 'Debtors A/c'],
  sol: 'Capital is owed by the firm to its proprietor, a credit balance. Cash, machinery and debtors are assets, which carry debit balances.',
}));
QQ('m_chk_nominal', mcq({
  t: 2, d: 2, c: 'application',
  stem: 'At the year end Zira Paints, an imagined firm, has to close several accounts. The one that is closed by transfer to the Trading Account, and not by a balance c/d, is',
  opts: ['Carriage Inwards A/c', 'Capital A/c', 'Debtors A/c', 'Furniture A/c'],
  sol: 'Carriage inwards is a direct expense, a nominal account, so it goes to the Trading Account. Capital, debtors and furniture are real or personal accounts and are carried down.',
}));
QQ('m_debit_balance_debtor', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'The account of a customer, Rajan Stores, in the ledger of Nilgiri Tea Estate (an imagined firm) closes with a debit balance. This means that',
  opts: ['Rajan Stores owes the amount to the firm', 'the firm owes the amount to Rajan Stores', 'Rajan Stores has paid more than it owes', 'the account is closed by transfer to the Trading Account'],
  sol: 'A customer who has been sold goods on credit is a debtor, and a debit balance is the amount he still has to pay. The reverse reading belongs to a credit balance, and personal accounts are carried down, not transferred.',
}));

// ================================================================ assertion-reason
QQ('ar_nominal', ar({
  t: 2, d: 3, c: 'analysis', verdict: 'both-true-explains',
  a: 'The Rent A/c of an imagined firm is closed by transfer to the Profit and Loss Account at the end of the year instead of being carried down.',
  r: 'A nominal account relates to the expenses or incomes of one period only, so its balance has no use in the next period.',
  sol: 'Both are true and the reason is why the account is closed by transfer: the expense belongs wholly to the year just ended.',
}));
QQ('ar_real_balance', ar({
  t: 2, d: 3, c: 'analysis', verdict: 'A-true-R-false',
  a: 'The Machinery A/c of an imagined firm is balanced at the year end and its debit balance is carried down to the next year.',
  r: 'Real and personal accounts are transferred to the Profit and Loss Account at the end of the year.',
  sol: 'The assertion is true: a real account is balanced with a balance c/d. The reason is false, since the transfer to the Profit and Loss Account is for nominal accounts.',
}));

// ================================================================ true-false, fill-blank
QQ('tf_nominal_cd', tf({
  t: 2, d: 2, c: 'understanding', ans: false,
  stem: 'Ghazipur Footwear, an imagined firm, ends the year by writing the balance of its Wages A/c as By Balance c/d, to be brought down as the opening balance of Wages next year.',
  sol: 'Wages is a nominal account. It is closed by transfer to the Trading Account and has no balance to carry down.',
}));
QQ('tf_cd_side', tf({
  t: 2, d: 2, c: 'understanding', ans: true,
  stem: 'When the credit side of an account of Mahoba Pipes, an imagined firm, is larger than the debit side, the balance is written on the debit side as To Balance c/d.',
  sol: 'The balance goes on the smaller side so that the two totals become equal. A larger credit side means the debit side is smaller, so the balance sits on the debit side.',
}));
QQ('fb_balance', fb({
  t: 2, d: 1, c: 'recall',
  stem: 'When the debit total of an account exceeds the credit total, the account has a ______ balance, which is written on the credit side as By Balance ______.',
  acc: [['debit'], ['c/d', 'carried down', 'carried down (c/d)']],
  sol: 'A debit balance is carried down on the credit side, as By Balance c/d.',
}));
QQ('fb_nominal', fb({
  t: 2, d: 2, c: 'recall',
  stem: 'Nominal accounts are closed by ______ to the Trading Account or the Profit and Loss Account, and so they show no balance ______.',
  acc: [['transfer', 'transferring'], ['c/d', 'carried down', 'brought down', 'b/d']],
  sol: 'Closing is done by transfer, and there is no balance carried down.',
}));

// ================================================================ numerical
const RS = { dr: [40000, 25000, 15500], cr: [18000, 22500, 9000] };
const RSL = ledger({ name: 'Cash A/c', dr: RS.dr.map((a, i) => [`To item ${i + 1}`, a]), cr: RS.cr.map((a, i) => [`By item ${i + 1}`, a]) });
same(RSL.balance, 31000, 'n_chk_balance');
QQ('n_chk_balance', numQ({
  t: 2, d: 2, c: 'application', value: RSL.balance,
  stem: 'The Cash A/c of Raxaul Spices, an imagined firm, has debit entries of ₹40,000, ₹25,000 and ₹15,500 and credit entries of ₹18,000, ₹22,500 and ₹9,000. Find the balance to be carried down (in ₹).',
  sol: `Debit side = ${inr(40000)} + ${inr(25000)} + ${inr(15500)} = ${inr(80500)}; credit side = ${inr(18000)} + ${inr(22500)} + ${inr(9000)} = ${inr(49500)}; balance c/d = ${inr(80500)} − ${inr(49500)} = ${rs(RSL.balance)}, a debit balance.`,
}));
const DH = [
  E1([['Cash A/c', 22000]], [['Capital A/c', 22000]], 'Being cash brought in by the proprietor'),
  E1([['Purchases A/c', 30000]], [['Cash A/c', 30000]], 'Being goods bought for cash'),
  E1([['Cash A/c', 41000]], [['Sales A/c', 41000]], 'Being goods sold for cash'),
  E1([['Rent A/c', 7500], ['Wages A/c', 4500]], [['Cash A/c', 12000]], 'Being rent and wages paid'),
  E1([['Cash A/c', 9500]], [['Interest Received A/c', 9500]], 'Being interest received'),
];
const DHL = post(DH, { 'Cash A/c': { side: 'dr', amount: 15000 } });
same(DHL['Cash A/c'].balance, 45500, 'Dhaulpur cash balance');
QQ('n_cash_balance', numQ({
  t: [1, 2], d: 3, c: 'application', value: DHL['Cash A/c'].balance,
  stem: 'Dhaulpur Dairy, an imagined firm, has a cash balance of ₹15,000 at the start of the month. During the month the journal shows cash brought in by the proprietor ₹22,000, goods bought for cash ₹30,000, goods sold for cash ₹41,000, rent ₹7,500 and wages ₹4,500 paid in cash (one entry) and interest received ₹9,500. After posting, the balance of the Cash A/c to be carried down is (in ₹)',
  sol: `Debit side = ${inr(15000)} + ${inr(22000)} + ${inr(41000)} + ${inr(9500)} = ${inr(87500)}; credit side = ${inr(30000)} + ${inr(12000)} = ${inr(42000)}; balance c/d = ${inr(87500)} − ${inr(42000)} = ${rs(45500)}.`,
}));
const DB = ledger({ name: 'Tarun Cycle Mart A/c', opening: { side: 'dr', amount: 36000 }, dr: [['To Sales A/c', 52000]], cr: [['By Cash A/c', 60000], ['By Sales Return A/c', 3500]] });
same(DB.balance, 24500, 'debtor balance');
QQ('n_debtor_balance', numQ({
  t: 2, d: 3, c: 'application', value: DB.balance,
  stem: 'Tarun Cycle Mart owed Chitradurga Spares, an imagined firm, ₹36,000 at the start of the quarter. The firm then sold it goods worth ₹52,000 on credit, received ₹60,000 in cash and took back goods worth ₹3,500. The balance of the account of Tarun Cycle Mart in the books of Chitradurga Spares is a debit balance of (in ₹)',
  sol: `Debit side = ${inr(36000)} + ${inr(52000)} = ${inr(88000)}; credit side = ${inr(60000)} + ${inr(3500)} = ${inr(63500)}; balance = ${inr(88000)} − ${inr(63500)} = ${rs(24500)}.`,
}));
const CT = ledger({ name: 'Anand Agencies A/c', opening: { side: 'cr', amount: 30000 }, dr: [['To Cash A/c', 55000]], cr: [['By Purchases A/c', 70000]] });
same(CT.total, 100000, 'n_total_after_cd');
same(CT.balance, -45000, 'creditor balance');
QQ('n_total_after_cd', numQ({
  t: 2, d: 3, c: 'application', value: CT.total,
  stem: 'Anand Agencies, a supplier of Hapur Stationers (an imagined firm), is owed ₹30,000 at the start of the month. Goods worth ₹70,000 are bought on credit and ₹55,000 is paid in cash. After the account is balanced, the total written at the foot of each side is (in ₹)',
  sol: `Credit side = ${inr(30000)} + ${inr(70000)} = ${inr(100000)}; debit side before balancing = ${inr(55000)}, so the balance ${inr(45000)} is added to the debit side as To Balance c/d, and each total = ${inr(55000)} + ${inr(45000)} = ${rs(100000)}.`,
}));

// ================================================================ short answer, 2 marks
QQ('s2_nominal_vs_real', short({
  t: 2, d: 3, c: 'understanding', marks: 2,
  stem: 'Why is the Rent A/c of a firm closed by transfer at the end of the year, while its Furniture A/c is balanced and carried down?',
  model: 'Rent is a **nominal account**: it records an expense of the year, which has been used up, so its total is transferred to the Profit and Loss Account and the account starts the next year with nothing.\n\nFurniture is a **real account**: the asset still exists and will be used next year, so its debit balance is carried down as Balance c/d and brought down as Balance b/d.',
  sol: 'Expense of one period against asset that lasts on.',
  scheme: [['Nominal account: expense of the year, closed by transfer, no balance carried', 1], ['Real account: asset still held, balance carried down and brought down', 1]],
}));
QQ('s2_debit_credit_balance', short({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'State what the closing balance of each of these accounts normally tells about the firm: (i) a debit balance in Cash A/c; (ii) a credit balance in a supplier\'s account.',
  model: '(i) A **debit balance in Cash A/c** shows the cash in hand; it is an asset.\n\n(ii) A **credit balance in a supplier\'s account** shows the amount the firm still owes to him; it is a liability.',
  sol: 'Cash is an asset, the supplier\'s account is a liability.',
  scheme: [['Debit balance of Cash A/c: cash in hand, an asset', 1], ['Credit balance of a supplier: amount payable, a liability', 1]],
}));
QQ('s2_cd_steps', short({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'List the steps in balancing a real or personal account at the end of the period.',
  model: '1. Add the debit side and the credit side separately.\n2. Find the difference of the two totals.\n3. Write the difference on the smaller side as **Balance c/d**, so the two sides are equal.\n4. Write the equal total on both sides on the same line.\n5. Bring the balance down as **Balance b/d** on the opposite side below the totals.',
  sol: 'Totals, difference, c/d, equal totals, b/d.',
  scheme: [['Both sides totalled and the difference found; c/d written on the smaller side', 1], ['Equal totals and the balance brought down as b/d on the opposite side', 1]],
}));

// ================================================================ short answer, 3 marks
const AA = [
  { date: '2 Jul', dr: [['Pooja Fabrics A/c', 64000]], cr: [['Sales A/c', 64000]], note: 'Being goods sold on credit' },
  { date: '19 Jul', dr: [['Cash A/c', 40000]], cr: [['Pooja Fabrics A/c', 40000]], note: 'Being cash received' },
  { date: '27 Jul', dr: [['Sales Return A/c', 4000]], cr: [['Pooja Fabrics A/c', 4000]], note: 'Being goods returned' },
];
const AAL = postD(AA, { openings: { 'Pooja Fabrics A/c': { side: 'dr', amount: 18000 } } });
same(AAL['Pooja Fabrics A/c'].balance, 38000, 'Pooja Fabrics balance');
QQ('s3_balance_account', short({
  t: 2, d: 3, c: 'application', marks: 3,
  stem: 'Pooja Fabrics owed Gonda Textiles, an imagined firm, ₹18,000 on 1 July 2027. During July Gonda sold it goods for ₹64,000 on credit, received ₹40,000 in cash and accepted a return of goods worth ₹4,000. Write the account of Pooja Fabrics in the ledger of Gonda Textiles and balance it on 31 July.',
  model: `${acct(AAL['Pooja Fabrics A/c'], { close: '31 Jul', open: '1 Aug', openingDate: '1 Jul' })}\n\nThe debit side is ${inr(82000)} and the credit side before balancing ${inr(44000)}, so the balance ${rs(38000)} (debit) is carried down on the credit side and brought down on the debit side.`,
  sol: 'Opening balance and sale on the debit side, receipts and return on the credit side, then balance.',
  scheme: [['Opening balance and sale on the debit side', 1], ['Cash received and return on the credit side', 1], ['Balance ₹38,000 c/d on the credit side, equal totals ₹82,000 and b/d on the debit side', 1]],
}));
QQ('s3_reading_balances', short({
  t: 2, d: 2, c: 'understanding', marks: 3,
  stem: 'Name the side of the balance and the nature of the account (asset, liability or capital) for each of these closing balances in the ledger of Pathri Pottery, an imagined firm: (i) Cash A/c; (ii) a creditor, Mohit Clay Suppliers; (iii) Capital A/c.',
  model: mdTable(['Account', 'Side of the balance', 'Nature'], [['Cash A/c', 'Debit', 'Asset (cash in hand)'], ['Mohit Clay Suppliers', 'Credit', 'Liability (amount payable)'], ['Capital A/c', 'Credit', 'Capital (owed to the proprietor)']]),
  sol: 'One mark for each account.',
  scheme: [['Cash A/c: debit balance, asset', 1], ['Creditor: credit balance, liability', 1], ['Capital A/c: credit balance, capital', 1]],
}));
const NC = [
  { date: '8 Aug', dr: [['Purchases A/c', 70000]], cr: [['Cash A/c', 70000]], note: 'Being goods bought' },
  { date: '30 Aug', dr: [['Purchases A/c', 25000]], cr: [['Cash A/c', 25000]], note: 'Being goods bought' },
  { date: '31 Aug', dr: [['Trading A/c', 95000]], cr: [['Purchases A/c', 95000]], note: 'Being Purchases transferred to Trading Account' },
  { date: '10 Aug', dr: [['Cash A/c', 130000]], cr: [['Sales A/c', 130000]], note: 'Being goods sold' },
  { date: '31 Aug', dr: [['Sales A/c', 130000]], cr: [['Trading A/c', 130000]], note: 'Being Sales transferred to Trading Account' },
];
const NCL = postD(NC);
same(NCL['Purchases A/c'].balance, 0, 'Purchases closed');
same(NCL['Sales A/c'].balance, 0, 'Sales closed');
QQ('s3_nominal_close', short({
  t: 2, d: 3, c: 'application', marks: 3,
  stem: 'Rewa Tools, an imagined firm, bought goods for cash twice during August, for ₹70,000 and ₹25,000, and sold goods for ₹1,30,000 in cash. Show how its Purchases A/c and Sales A/c are closed on 31 August by transfer to the Trading Account, with the closing journal entries.',
  model: `Journal: Trading A/c Dr ${inr(95000)} To Purchases A/c ${inr(95000)}; Sales A/c Dr ${inr(130000)} To Trading A/c ${inr(130000)}.\n\n${postedOnly(NCL['Purchases A/c']).md}\n\n${postedOnly(NCL['Sales A/c']).md}\n\nBoth accounts now have equal sides and no balance c/d.`,
  sol: 'Purchases is credited, Sales is debited, each by its total.',
  scheme: [['Total of Purchases found (₹95,000) and credited', 1], ['Sales A/c debited with its total ₹1,30,000, and the Trading A/c entries', 1], ['Both accounts shown closed with equal sides and no balance c/d', 1]],
}));

// ================================================================ long answer, 5 marks
const AG = {
  opening: { date: '1 Jan 2028', dr: [['Cash A/c', 48000], ['Stock A/c', 72000]], cr: [['Anand Agencies A/c', 32000], ['Capital A/c', 88000]], note: 'Being the opening balances brought forward' },
  txn: [
    E1([['Purchases A/c', 56000]], [['Anand Agencies A/c', 56000]], 'Being goods bought on credit from Anand Agencies', '5 Jan'),
    E1([['Cash A/c', 62000]], [['Sales A/c', 62000]], 'Being goods sold for cash', '9 Jan'),
    E1([['Anand Agencies A/c', 40000]], [['Cash A/c', 40000]], 'Being cash paid to Anand Agencies', '16 Jan'),
    E1([['Cash A/c', 34000]], [['Sales A/c', 34000]], 'Being goods sold for cash', '21 Jan'),
    E1([['Anand Agencies A/c', 3000]], [['Purchases Return A/c', 3000]], 'Being goods returned to Anand Agencies', '24 Jan'),
    E1([['Carriage Inwards A/c', 2500]], [['Cash A/c', 2500]], 'Being carriage paid in cash', '28 Jan'),
  ],
};
const AGL = postD(AG.txn, { openings: openingsFrom(AG.opening) });
same(AGL['Cash A/c'].balance, 101500, 'Agarwal cash balance');
same(AGL['Anand Agencies A/c'].balance, -45000, 'Anand creditor balance');
same(AGL['Sales A/c'].balance, -96000, 'Sales credit total');
const AGclose = [
  E1([['Sales A/c', 96000]], [['Trading A/c', 96000]], 'Being Sales transferred to Trading Account', '31 Jan'),
];
const AGL2 = postD([...AG.txn, ...AGclose], { openings: openingsFrom(AG.opening) });
same(AGL2['Sales A/c'].balance, 0, 'Sales closed');
const agOpt = { close: '31 Jan 2028', open: '1 Feb 2028', openingDate: '1 Jan 2028' };
QQ('l5_balance_close', long({
  t: 2, d: 4, c: 'application', marks: 5,
  stem: `Pune Sports House, an imagined firm, began 2028 with cash ₹48,000, stock ₹72,000, a creditor Anand Agencies ₹32,000 and capital ₹88,000. In January 2028 the journal shows: 5 Jan goods bought on credit from Anand Agencies ₹56,000; 9 Jan cash sales ₹62,000; 16 Jan cash paid to Anand Agencies ₹40,000; 21 Jan cash sales ₹34,000; 24 Jan goods returned to Anand Agencies ₹3,000; 28 Jan carriage on purchases paid in cash ₹2,500. (a) Prepare and balance the Cash A/c [2]. (b) Prepare and balance the account of Anand Agencies [1]. (c) Close the Sales A/c by transfer to the Trading Account on 31 January and show the entry [1]. (d) State why the Sales A/c has no balance c/d but the Cash A/c has [1].`,
  model: `**(a)**\n\n${acct(AGL['Cash A/c'], agOpt)}\n\n**(b)**\n\n${acct(AGL['Anand Agencies A/c'], agOpt)}\n\n**(c)** Entry: Sales A/c Dr ${inr(96000)} To Trading A/c ${inr(96000)}.\n\n${postedOnly(AGL2['Sales A/c']).md}\n\n**(d)** Sales is a nominal account, closed by transfer, so it shows no balance carried down; Cash is a real account and its debit balance of ${rs(101500)} is carried down.`,
  sol: 'Opening balances as b/d, each entry on its side, balance, and transfer of Sales.',
  scheme: [['Cash A/c: opening balance, receipts and payments on the correct sides', 1], ['Cash A/c: balance ₹1,01,500 c/d and b/d', 1], ['Anand Agencies A/c: credit balance ₹45,000 c/d and b/d', 1], ['Sales A/c closed by transfer of ₹96,000, with the entry', 1], ['Nominal against real account explained', 1]],
}));
// faulty cash account for error finding
const BM = { open: 40000, cashSale: 25000, recd: 18000, rent: 6000, creditor: 22000, wages: 9000 };
const BMgood = ledger({ name: 'Cash A/c', opening: { side: 'dr', amount: BM.open }, dr: [['To Sales A/c', BM.cashSale], ['To Cash from debtor', BM.recd]], cr: [['By Rent A/c', BM.rent], ['By Creditor A/c', BM.creditor], ['By Wages A/c', BM.wages]] });
same(BMgood.balance, 46000, 'Bidar cash balance');
const BMbad = ledger({ name: 'Cash A/c', dr: [['To Cash from debtor', BM.recd]], cr: [['By Balance b/d', BM.open], ['By Sales A/c', BM.cashSale], ['By Rent A/c', BM.rent], ['By Creditor A/c', BM.creditor], ['By Wages A/c', BM.wages]] });
same(BMbad.balance, -(BM.open + BM.cashSale + BM.rent + BM.creditor + BM.wages - BM.recd), 'Bidar faulty balance');
check(BMbad.balance < 0, 'faulty cash shows a credit balance');
QQ('l5_errors', long({
  t: 2, d: 5, c: 'evaluation', marks: 5,
  stem: `The clerk of Bidar Metals, an imagined firm, wrote its Cash A/c for January 2028 as shown below and balanced it.\n\n${mdTable(BMbad.headers, BMbad.rows)}\n\nThe journal had shown: opening cash ₹40,000; cash sales ₹25,000; cash received from a debtor ₹18,000; rent ₹6,000, a creditor ₹22,000 and wages ₹9,000 paid in cash. (a) Point out three mistakes in the account [3]. (b) Rewrite the account correctly and give its balance [2].`,
  model: `**(a)** (i) The opening cash balance ${rs(40000)} is written on the credit side; an asset balance belongs on the debit side as To Balance b/d. (ii) The cash sales ${rs(25000)} are written on the credit side; receipts of cash are debited. (iii) The account closes with a credit balance of ${rs(-BMbad.balance)}, which is impossible for cash in hand and so signals the errors.\n\n**(b)**\n\n${lmd(BMgood)}\n\nThe correct balance is a debit balance of ${rs(46000)}.`,
  sol: 'Check each item against the side it should be on, then rebuild.',
  scheme: [['Opening balance on the wrong side identified', 1], ['Cash sales on the wrong side identified', 1], ['Impossible credit balance of cash recognised as the sign of the errors', 1], ['Correct account with every item on its side', 1], ['Correct balance ₹46,000 c/d and b/d', 1]],
}));
void sum; void showL;
